#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(httr);library(readr);library(dplyr);library(igraph)})
options(stringsAsFactors=FALSE)
root <- normalizePath('.',mustWork=TRUE); outdir <- file.path(root,'results/network_ppi'); figdir <- file.path(outdir,'figures'); dir.create(figdir,recursive=TRUE,showWarnings=FALSE)
core <- c('Txnip','Nlrp3','Casp1','Gsdmd','Il1b','Il18')
files <- c(de=file.path(root,'results/12wk_primary/de/primary__HO_Safflower_vs_Safflower.csv'),le=file.path(root,'results/12wk_primary/scores/primary__HO_Safflower_vs_Safflower__leading_edge_genes.csv'),im=file.path(root,'results/12wk_primary/immune/12wk_immune_marker_sets_filtered.csv'))
if(any(!file.exists(files))) stop('Missing input: ',paste(files[!file.exists(files)],collapse=', '))
canon <- function(x) sub('\\..*$','',trimws(as.character(x)))
de <- read.csv(files['de'],check.names=FALSE); de$gene_symbol <- canon(de$gene_symbol); de <- de %>% filter(nzchar(gene_symbol),is.finite(adj.P.Val),is.finite(logFC),adj.P.Val<.05,abs(logFC)>=1)
de_tbl <- bind_rows(de %>% arrange(desc(logFC)) %>% slice_head(n=25) %>% transmute(gene=gene_symbol,source='DE_top',source_module='DE_top_up'),de %>% arrange(logFC) %>% slice_head(n=25) %>% transmute(gene=gene_symbol,source='DE_top',source_module='DE_top_down'))
le <- read.csv(files['le'],check.names=FALSE); le_tbl <- tibble(gene=unique(canon(le$gene)),source='leading_edge',source_module='leading_edge')
im <- read.csv(files['im'],check.names=FALSE); im$gene <- canon(im$gene); im_tbl <- im %>% filter(nzchar(gene)) %>% transmute(gene,source='immune_marker',source_module=paste0('immune:',module)) %>% distinct()
input_long <- bind_rows(tibble(gene=core,source='PSPS_core',source_module='PSPS_core'),de_tbl,le_tbl,im_tbl) %>% filter(nzchar(gene)) %>% distinct()
collapse <- function(x) paste(sort(unique(x)),collapse=';')
input_tbl <- input_long %>% group_by(gene) %>% summarise(source=collapse(source),source_module=collapse(source_module),.groups='drop') %>% arrange(gene)
post_string <- function(endpoint,body){
  # STRING occasionally returns a transient 404 for a large payload; retry with
  # the same request to keep the analysis reproducible without lowering the score threshold.
  for (attempt in seq_len(3)) {
    r <- POST(paste0('https://string-db.org/api/tsv/',endpoint),body=body,encode='form',timeout(90))
    if (status_code(r) < 300) return(content(r,as='text',encoding='UTF-8'))
    if (attempt < 3) Sys.sleep(attempt) else stop('STRING API failed: ',status_code(r))
  }
}
payload <- paste(input_tbl$gene,collapse='\r'); writeLines(input_tbl$gene,file.path(outdir,'ppi_query_genes.txt')); writeLines(as.character(nchar(payload)),file.path(outdir,'ppi_query_chars.txt'))
maptxt <- post_string('get_string_ids',list(identifiers=payload,species='10090',echo_query='1',caller_identity='psps_network')); mapping <- read.delim(textConnection(maptxt),check.names=FALSE); mapping <- mapping %>% transmute(query_gene=canon(queryItem),string_id=stringId,preferred_name=preferredName,ncbi_taxon_id=ncbiTaxonId,taxon_name=taxonName) %>% distinct(query_gene,.keep_all=TRUE)
nettxt <- post_string('network',list(identifiers=payload,species='10090',required_score='700',caller_identity='psps_network')); writeLines(nettxt,file.path(outdir,'string_network_raw.tsv')); raw <- read.delim(textConnection(nettxt),check.names=FALSE); if(!nrow(raw))stop('No STRING edges returned')
edges <- raw %>% transmute(string_id_a=stringId_A,string_id_b=stringId_B,from=preferredName_A,to=preferredName_B,ncbi_taxon_id=ncbiTaxonId,combined_score=as.numeric(score),nscore=as.numeric(nscore),fscore=as.numeric(fscore),pscore=as.numeric(pscore),ascore=as.numeric(ascore),escore=as.numeric(escore),dscore=as.numeric(dscore),tscore=as.numeric(tscore)) %>% filter(is.finite(combined_score)) %>% mutate(a=pmin(tolower(from),tolower(to)),b=pmax(tolower(from),tolower(to))) %>% group_by(a,b) %>% slice_max(combined_score,n=1,with_ties=FALSE) %>% ungroup() %>% select(-a,-b) %>% mutate(evidence_type='数据库先验')
network_names <- unique(c(edges$from,edges$to)); deg <- table(c(edges$from,edges$to)); nodes <- input_tbl %>% rename(query_gene=gene) %>% left_join(mapping,by='query_gene') %>% mutate(mapped=!is.na(string_id),in_network=!is.na(preferred_name)&preferred_name%in%network_names,degree=as.integer(ifelse(is.na(preferred_name),0,deg[preferred_name])),degree=ifelse(is.na(degree),0L,degree)) %>% arrange(desc(degree),query_gene)
write_csv(input_tbl,file.path(outdir,'ppi_input_genes.csv'));write_csv(mapping,file.path(outdir,'ppi_string_id_mapping.csv'));write_csv(nodes,file.path(outdir,'ppi_nodes.csv'));write_csv(edges,file.path(outdir,'ppi_edges.csv'))
g <- graph_from_data_frame(edges %>% select(from,to,combined_score,evidence_type),directed=FALSE); V(g)$degree <- degree(g); V(g)$is_core <- V(g)$name%in%core
V(g)$source <- vapply(V(g)$name,function(n){hit<-nodes$source[tolower(nodes$preferred_name)==tolower(n)];if(!length(hit))'STRING_network' else hit[[1]]},character(1)); comps <- components(g); hubs <- nodes %>% filter(in_network) %>% arrange(desc(degree),query_gene) %>% slice_head(n=20)
summary <- tibble(input_genes=nrow(input_tbl),mapped_genes=sum(nodes$mapped),genes_in_network=sum(nodes$in_network),network_nodes=vcount(g),network_edges=ecount(g),density=edge_density(g),connected_components=comps$no,largest_component_nodes=max(comps$csize),score_threshold=700,min_edge_score=min(edges$combined_score),median_edge_score=median(edges$combined_score),max_edge_score=max(edges$combined_score));write_csv(summary,file.path(outdir,'ppi_network_summary.csv'));write_csv(hubs,file.path(outdir,'ppi_top_hubs.csv'))
# Base igraph publication-ready overview. Database edges are prior evidence only.
colour_for <- function(s){if(grepl('PSPS_core',s,fixed=TRUE))'#D73027' else if(grepl('DE_top',s,fixed=TRUE))'#4575B4' else if(grepl('leading_edge',s,fixed=TRUE))'#66BD63' else if(grepl('immune_marker',s,fixed=TRUE))'#FDAE61' else '#BDBDBD'}
V(g)$color <- vapply(V(g)$source,colour_for,character(1));V(g)$size <- 4+1.3*sqrt(pmax(1,V(g)$degree));V(g)$frame.color <- ifelse(V(g)$is_core,'#000000','#FFFFFF');V(g)$frame.width <- ifelse(V(g)$is_core,2,.5);E(g)$width <- .5+3.5*(E(g)$combined_score-min(E(g)$combined_score))/max(1e-6,max(E(g)$combined_score)-min(E(g)$combined_score));E(g)$color <- grDevices::adjustcolor('#737373',alpha.f=.2);labels<-unique(c(core,hubs$query_gene[seq_len(min(10,nrow(hubs)))]));V(g)$label<-ifelse(V(g)$name%in%labels,V(g)$name,NA);V(g)$label.cex<-.65;set.seed(20260929);lay<-layout_with_fr(g,weights=E(g)$combined_score,niter=2000)
pdf(file.path(figdir,'STRING_PPI_high_confidence_network.pdf'),12,10,useDingbats=FALSE);par(mar=c(1,1,4,1));plot(g,layout=lay,asp=0,main='STRING prior network: PSPS + DE/leading-edge/immune genes\nMus musculus; combined score >= 700');legend('topleft',legend=c('PSPS core','DE top','leading edge','immune marker','other/mixed'),col=c('#D73027','#4575B4','#66BD63','#FDAE61','#BDBDBD'),pch=19,pt.cex=1.3,bty='n');dev.off()
png(file.path(figdir,'STRING_PPI_high_confidence_network.png'),2400,2000,res=220);par(mar=c(1,1,4,1));plot(g,layout=lay,asp=0,main='STRING prior network: PSPS + DE/leading-edge/immune genes\nMus musculus; combined score >= 700');legend('topleft',legend=c('PSPS core','DE top','leading edge','immune marker','other/mixed'),col=c('#D73027','#4575B4','#66BD63','#FDAE61','#BDBDBD'),pch=19,pt.cex=1.3,bty='n');dev.off()
manifest <- c('STRING high-confidence prior network for the PSPS candidate axis',paste0('Input genes: ',nrow(input_tbl),' (PSPS core + top DE + leading-edge + immune marker genes).'),'Top DE: 25 upregulated and 25 downregulated genes, adj.P.Val < 0.05 and |logFC| >= 1.','Organism: Mus musculus (taxon 10090); STRING required_score = 700.','Network edges are STRING database prior evidence (combined evidence score), not experimentally demonstrated interactions in this study.','The graph is hypothesis-generating and does not prove physical binding, pathway directionality, or causality.',paste0('Returned network: ',vcount(g),' nodes, ',ecount(g),' unique undirected edges; ',comps$no,' connected component(s).'),'See ppi_nodes.csv, ppi_edges.csv, ppi_network_summary.csv, and figures/.');writeLines(manifest,file.path(outdir,'README.md'));writeLines(capture.output(sessionInfo()),file.path(outdir,'sessionInfo.txt'));writeLines(capture.output(summary),file.path(outdir,'run_log.txt'));cat(paste(manifest,collapse='\\n'),'\\n')
